
const FN=['Operations & Analytics','Recruitment','Business Development','HR Outsourcing','Learning & Development','Finance','Payroll','Human Resources','HR Consulting'];
const DEFINITIONS=[["Operations & Analytics", [["Action Tracker Discipline", "100% bi-weekly Team action trackers issued within 48 hours.", "percent", 100, "higher"], ["Performance Dashboard", "Monthly cross-functional performance dashboard submitted on time.", "count", 1, "higher"], ["HR Technology Transformation", "Progress the agreed monthly milestone for a technology initiative improving an operational or process opportunity.", "unconfigured", null, "higher"], ["Follow-Through", "≥90% Team actions followed up by due date.", "percent", 90, "higher"], ["Team Contribution", "≥90% Team attendance plus substantive contribution to business/culture improvement.", "percent", 90, "higher"]]], ["Recruitment", [["Vacancy Tracking", "100% assigned active vacancies updated weekly.", "percent", 100, "higher"], ["SLA Adherence", "≥90% candidate/client actions completed within agreed SLA.", "percent", 90, "higher"], ["Bottleneck Analysis", "Monthly analysis of recruitment delays/candidate experience/conversion bottlenecks.", "count", 1, "higher"], ["HR Technology Transformation", "Progress the agreed monthly milestone for a technology initiative improving recruitment delivery or candidate experience.", "unconfigured", null, "higher"], ["Team Contribution", "≥90% Team attendance and completion of assigned actions.", "percent", 90, "higher"]]], ["Business Development", [["Prospect Engagement", "Achieve agreed monthly qualified prospect engagement target.", "unconfigured", null, "higher"], ["Pipeline Currency", "Maintain 100% current prospect/pipeline tracker.", "percent", 100, "higher"], ["Opportunity Generation", "Generate minimum three qualified cross-sell/new-business opportunities monthly.", "count", 3, "higher"], ["HR Technology Market Opportunity", "Progress the agreed monthly milestone on a client HR Technology need, market opportunity or commercial proposition.", "unconfigured", null, "higher"], ["Team Contribution", "≥90% Team attendance and assigned-action completion.", "percent", 90, "higher"]]], ["HR Outsourcing", [["Issue Tracking", "100% assigned client/staff issues recorded and tracked.", "percent", 100, "higher"], ["Escalation Handling", "≥90% assigned escalations actioned within SLA.", "percent", 90, "higher"], ["Recurring Issue Analysis", "Monthly analysis of recurring outsourced-staff/client issues.", "count", 1, "higher"], ["HR Technology Transformation", "Progress the agreed monthly milestone for a technology initiative improving outsourced client or workforce service.", "unconfigured", null, "higher"], ["Team Contribution", "≥90% Team attendance and assigned-action completion.", "percent", 90, "higher"]]], ["Learning & Development", [["Programme Tracking", "100% programme/training tracker updated by deadline.", "percent", 100, "higher"], ["Capability Needs Analysis", "Identify minimum one evidence-based internal/client capability need monthly.", "count", 1, "higher"], ["Academy Opportunities", "Generate/progress minimum two qualified Academy opportunities monthly.", "count", 2, "higher"], ["HR Technology Transformation", "Progress the agreed monthly milestone for a digital learning initiative strengthening Academy delivery.", "unconfigured", null, "higher"], ["Team Contribution", "≥90% Team attendance and assigned-action completion.", "percent", 90, "higher"]]], ["Finance", [["Processing Accuracy", "≥98% accuracy in assigned financial processing/reconciliation.", "percent", 98, "higher"], ["Month-End Discipline", "100% assigned month-end activities completed by deadline.", "percent", 100, "higher"], ["HR Technology Transformation", "Progress the agreed monthly milestone for a technology initiative improving financial processing or controls.", "unconfigured", null, "higher"], ["Finance Insight", "Produce one Finance insight on cost, revenue, collections or efficiency monthly.", "count", 1, "higher"], ["Team Contribution", "≥90% Team attendance and assigned-action completion.", "percent", 90, "higher"]]], ["Payroll", [["Processing Accuracy", "≥99% accuracy on assigned payroll processing/checking.", "percent", 99, "higher"], ["Query Resolution", "≥90% payroll queries resolved within agreed SLA.", "percent", 90, "higher"], ["Exception Logging", "100% payroll exceptions/errors logged with root cause and corrective action.", "percent", 100, "higher"], ["HR Technology Transformation", "Progress the agreed monthly milestone for a payroll technology initiative improving accuracy or efficiency.", "unconfigured", null, "higher"], ["Team Contribution", "≥90% Team attendance and assigned-action completion.", "percent", 90, "higher"]]], ["Human Resources", [["Culture Pulse Reporting", "Monthly employee/culture pulse summary supported by staff feedback/data.", "count", 1, "higher"], ["HR Request SLA", "≥90% assigned HR employee requests completed within SLA.", "percent", 90, "higher"], ["Engagement Diagnostics", "Identify minimum one culture/engagement/policy-awareness issue with recommended intervention monthly.", "count", 1, "higher"], ["HR Technology Transformation", "Progress the agreed monthly milestone for a technology initiative improving employee experience or HR service.", "unconfigured", null, "higher"], ["Team Contribution", "≥90% Team attendance and assigned-action completion.", "percent", 90, "higher"]]], ["HR Consulting", [["Milestone Delivery", "≥90% assigned consulting milestones delivered by deadline.", "percent", 90, "higher"], ["Project Tracker Currency", "100% assigned project tracker information updated weekly.", "percent", 100, "higher"], ["Client/HR Insight", "Minimum one research-backed client/HR insight monthly.", "count", 1, "higher"], ["HR Technology Transformation", "Progress the agreed monthly milestone for a technology initiative strengthening consulting delivery.", "unconfigured", null, "higher"], ["Team Contribution", "≥90% Team attendance and assigned-action completion.", "percent", 90, "higher"]]]];
const OPS_TEAM=FN[0];
const OPS_IDS=['ops-action-tracker-v1','ops-performance-dashboard-v1','ops-hr-technology-v1','ops-follow-through-v1','ops-team-contribution-v1'];
const OPS_EVIDENCE='Team action trackers, dashboard submission log and attendance/contribution records.';
function operationsKpis(){return state.kpis.filter(k=>k.team===OPS_TEAM&&!k.archived);}
function activeKpis(){return state.kpis.filter(k=>!k.archived);}
function legacyOperationsNotice(){const ids=new Set(operationsKpis().map(k=>k.id));const archived=state.kpis.filter(k=>k.team===OPS_TEAM&&!ids.has(k.id));return `<div class="help"><strong>Operations &amp; Analytics Officer · Five monthly KPIs</strong><p>Evidence source: ${OPS_EVIDENCE}</p><p>Performance Dashboard and HR Technology Transformation require an agreed scoring unit and numeric target before scoring; no target has been invented. Team Contribution requires evidence of substantive contribution as well as attendance.</p>${archived.length?`<p>Manual mapping review required: ${archived.map(k=>esc(k.name)).join(', ')}. Historical definitions and entries are preserved in backups, excluded from current inputs and reports, and have not been reassigned.</p>`:''}</div>`;}
function operationsNotice(){return '<div class="help">Five official monthly KPIs. For monthly deliverables, enter 1 only when completed by the stated deadline. Technology milestones and agreed prospect targets require administrator scoring setup. Team Contribution requires both attendance and assigned-action/contribution evidence.</div>';}
const KEY='nextgen_dashboard_2026_v1';const now=new Date();const currentMonth=now.toISOString().slice(0,7);let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch(e){};if(!state||!Array.isArray(state.kpis)){state={kpis:DEFINITIONS.flatMap((f,ix)=>f[1].map((k,j)=>({id:'official-2026-'+ix+'-'+j,officialKpi:true,team:FN[ix],name:k[0],description:k[1],unit:k[2],target:k[3],direction:k[4],weight:1}))),actuals:{},notes:{}}}state.actuals ||= {};state.notes ||= {};let month=currentMonth,view='overview',chosenTeam=FN[0],editId=null;
function persist(){localStorage.setItem(KEY,JSON.stringify(state))}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function titleTeam(s){return s==='Human Resources'?'HR':s}function formatVal(x,u){if(x===null||x===undefined||x==='')return '—';if(u==='ghs')return 'GH₵ '+Number(x).toLocaleString('en-GH',{maximumFractionDigits:1});if(u==='percent')return Number(x).toLocaleString()+'%';if(u==='days')return Number(x).toLocaleString()+' d';return Number(x).toLocaleString()}function getRecord(k,m=month){return (state.actuals[m]||{})[k.id]||{}}function result(k,m=month){let r=getRecord(k,m),a=r.actual;if(k.unit==='unconfigured'||(r.target??k.target)==null)return null;if(a===null||a===undefined||a==='')return null;let t=Number(r.target??k.target),v=Number(a);if(!Number.isFinite(v)||!Number.isFinite(t))return null;if(k.direction==='lower'){return v===0?100:t===0?0:Math.min(100,100*t/v)}return t===0?(v>0?100:100):Math.min(100,100*v/t)}// Monthly totals use all five expected KPIs and all nine functions.
const KPIS_PER_FUNCTION=5;
function statTeam(team,m=month){const ks=activeKpis().filter(k=>k.team===team),entered=ks.filter(k=>result(k,m)!==null),sum=entered.reduce((a,k)=>a+result(k,m),0);return{score:Math.min(100,sum/KPIS_PER_FUNCTION),count:entered.length,total:KPIS_PER_FUNCTION};}
function allStat(){const entries=FN.map(f=>statTeam(f));return{entries,score:entries.reduce((a,x)=>a+x.score,0)/FN.length,submitted:entries.filter(x=>x.count===x.total).length,filled:entries.reduce((a,x)=>a+x.count,0),total:FN.length*KPIS_PER_FUNCTION};}
function teamStatus(z){return z.count===0?'Not reported':statusText(z.score);}
function teamMood(z){return z.count===0?'none':mood(z.score);}
function kpiStatus(k,m=month){const r=getRecord(k,m);return k.unit==='unconfigured'||(r.target??k.target)==null?'Scoring setup required':statusText(result(k,m));}
function mood(v){return v===null?'none':v>=90?'good':v>=70?'warning':'poor'}function statusText(v){return v===null?'Not reported':v>=90?'On track':v>=70?'Watch':'Needs attention'}function bar(v){return `<div class="progress"><span class="${mood(v)}" style="width:${Math.round(v||0)}%"></span></div>`}function score(v){return v===null?'—':Number(v.toFixed(1))+'%'}function monthName(m){return new Date(m+'-01T12:00:00').toLocaleString('en-GB',{month:'long',year:'numeric'})}function months(){const out=[];let d=new Date();d.setDate(1);d.setMonth(d.getMonth()+6);for(let i=0;i<30;i++){out.push(d.toISOString().slice(0,7));d.setMonth(d.getMonth()-1)}if(!out.includes(month))out.unshift(month);return out}function toast(msg){let el=document.getElementById('toast');el.textContent=msg;el.style.display='block';setTimeout(()=>el.style.display='none',3000)}function render(){document.getElementById('monthSelect').innerHTML=months().map(m=>`<option value="${m}" ${m===month?'selected':''}>${monthName(m)}</option>`).join('');document.querySelectorAll('.navbtn').forEach(b=>b.classList.toggle('on',b.dataset.view===view));let meta={overview:['Performance Overview','Monthly cross-functional performance tracking'],functions:['Functional Teams','Performance across nine business functions'],updates:['KPI Updates','Enter targets, results and performance notes'],reports:['Monthly Report','A shareable management summary'],trends:['Department Comparisons','Six-month cross-functional performance'],slides:['Leadership Presentation','Boardroom-ready monthly briefing'],settings:['Settings & Data','Manage indicators and back up your dashboard']}[view];document.getElementById('pageTitle').textContent=meta[0];document.getElementById('pageDesc').textContent=meta[1]+' · '+monthName(month);document.getElementById('screen').innerHTML=({overview:overview,functions:teamsPage,updates:updatesPage,reports:reportsPage,trends:trendsPage,slides:slidesPage,settings:settingsPage}[view])();bindScreen()}
function heroArt(){return `<div class="work-scene" role="img" aria-label="Animated illustration of an analyst typing KPI figures, reviewing performance charts and sending a report"><div class="work-stage-head"><span class="phase p1">01 · ENTER KPI DATA</span><span class="phase p2">02 · REVIEW RESULTS</span><span class="phase p3">03 · SEND REPORT</span></div><div class="work-character"><svg class="hero-anime" viewBox="0 0 240 220" aria-hidden="true" role="img"><g><ellipse cx="150" cy="202" rx="72" ry="10" fill="rgba(22,31,67,.18)"/><rect class="desk" x="88" y="176" width="120" height="10" rx="5"/><path class="hair" d="M165 54c11 8 18 21 18 37 0 35-24 61-54 61-31 0-56-25-56-57 0-31 22-55 56-55 15 0 27 5 36 14z"/><path class="hair-shade" d="M170 61c7 8 10 18 10 30 0 35-24 61-54 61-12 0-23-4-33-12 9 4 19 6 29 6 35 0 60-28 60-60 0-8-3-17-7-25z"/><path class="skin" d="M101 68c-7 8-10 19-10 31 0 26 15 46 39 46s40-19 40-44c0-13-5-25-12-33h-57z"/><path class="skin-shade" d="M127 105h28c-4 15-15 26-32 30 8-8 8-18 4-30z" opacity=".45"/><ellipse class="cheek" cx="112" cy="106" rx="7" ry="4"/><ellipse class="cheek" cx="148" cy="106" rx="7" ry="4"/><g class="blink"><ellipse class="eye" cx="116" cy="95" rx="4.4" ry="6.4"/><ellipse class="eye" cx="145" cy="95" rx="4.4" ry="6.4"/><circle cx="117" cy="93" r="1.2" fill="#fff"/><circle cx="146" cy="93" r="1.2" fill="#fff"/></g><path class="line" d="M124 111c4 3 9 3 13 0"/><path class="line" d="M106 84c5-4 12-5 17-2"/><path class="line" d="M136 83c6-3 12-2 17 2"/><path class="hair" d="M92 80c9-8 11-22 19-29 6-5 14-8 25-8 24 0 39 15 42 35-9-9-19-15-28-17-16-3-29 2-39 10-7 6-13 12-19 9z"/><path class="skin" d="M123 118c1 10-2 16-7 21h23c-6-5-8-11-8-21z"/><path class="blazer" d="M91 191c2-26 11-45 28-54l11 14 13-14c18 9 29 29 31 54H91z"/><path class="shirt" d="M117 141h29v50h-29z"/><path class="tie" d="M131 144l8 10-5 15 5 22h-16l5-22-5-15z"/><path class="line" d="M117 139l13 12 13-12"/><g class="laptop-block"><path class="laptop" d="M152 149h34c5 0 9 4 9 9v20h-52v-20c0-5 4-9 9-9z"/><rect class="laptop-screen" x="148" y="153" width="42" height="21" rx="3"/><rect class="screen-bar" x="153" y="159" width="26" height="4" rx="2"/><rect class="screen-bar" x="153" y="166" width="18" height="3" rx="1.5" opacity=".8"/></g><g class="arm-front"><path class="skin" d="M139 147c7 1 13 6 15 13l5 16-12 4-4-13c-2-5-5-9-10-12z"/><path class="blazer" d="M131 142c7 0 13 3 18 8l-9 10c-3-4-6-6-10-7z"/></g><path class="skin" d="M116 150c-5 2-10 6-13 12l-7 14 11 5 6-11c2-4 5-7 8-10z"/><path class="blazer" d="M120 144c-7 1-14 5-19 12l11 7c3-5 6-7 11-9z"/></g></svg></div><div class="work-props"><div class="work-laptop"><span class="screen-header">NEXTGEN / KPI INPUT</span><span class="screen-line one"></span><span class="screen-line two"></span><span class="screen-line three"></span><span class="typing-caret"></span></div><div class="work-review"><span class="review-title">Performance review</span><span class="review-bar rb1"></span><span class="review-bar rb2"></span><span class="review-bar rb3"></span><span class="review-check">✓</span></div><div class="work-report"><span class="report-top">MONTHLY REPORT</span><span class="report-line"></span><span class="report-line short"></span><span class="report-graph">▂ ▄ ▆ █</span><span class="report-sent">✓ SENT</span></div></div><div class="work-counter"><span class="dot-step d1"></span><span class="dot-step d2"></span><span class="dot-step d3"></span><span class="counter-label">ANALYSE → REPORT → SHARE</span></div></div>`}
function heroShell(kicker,title,text,chip){return `<div class="hero"><div class="hero-main"><div class="kicker">${kicker}</div><h2>${title}</h2><p>${text}</p><span class="hero-chip">${chip}</span></div>${heroArt()}</div>`}
function overview(){
 let s=allStat(),active=s.entries.filter(x=>x.count>0);
 let positive=active.filter(x=>x.score>=90).length;
 let needs=active.filter(x=>x.score<70).length;
 let months6=months().filter(m=>m<=month).slice(0,6).reverse();
 return `${heroShell('MONTHLY LEADERSHIP INTELLIGENCE','Performance at a glance.','One clear view of progress across all nine leadership functions.','✦ '+monthName(month))}
 <div class="ng-overview">
 <div class="stats">
 <div class="card stat"><div class="k">Overall performance</div><div class="v">${score(s.score)}</div><div class="hint">All 9 functions · 5 KPIs each</div></div>
 <div class="card stat"><div class="k">Reporting completion</div><div class="v">${Math.round(100*s.filled/Math.max(s.total,1))}%</div><div class="hint">${s.filled} of ${s.total} KPI updates</div></div>
 <div class="card stat"><div class="k">Functions completed</div><div class="v">${s.submitted}<span class="muted" style="font-size:17px"> / 9</span></div><div class="hint">Fully reported this month</div></div>
 <div class="card stat"><div class="k">Functions on track</div><div class="v">${positive}</div><div class="hint">${needs} need attention · ${s.entries.filter(x=>x.count===0).length} not reported</div></div>
 </div>
 <section class="ng-team-section">
 <div class="rowhead"><div><div class="ng-eyebrow">TEAM PERFORMANCE</div><h2>All nine functions</h2><p class="sub">Select any card to see its KPIs and monthly progress.</p></div><button class="btn sm" data-onclick="changeView('functions')">View all functions →</button></div>
 <div class="teams">${FN.map(f=>teamCard(f)).join('')}</div>
 </section>
 <section class="ng-insights">
 <div class="rowhead"><div><div class="ng-eyebrow">PERFORMANCE ANALYTICS</div><h2>Monthly insights</h2></div><button class="btn sm" data-onclick="changeView('trends')">Compare months →</button></div>
 <div class="ng-insights-grid">
 <div class="card pad ng-performance"><div class="rowhead"><h2>Functional performance</h2><span class="small">Current month</span></div><div class="group-list">${FN.map(f=>{let z=statTeam(f);return `<div class="group-item"><div class="label">${esc(f)}</div>${bar(z.score)}<strong>${score(z.score)}</strong></div>`}).join('')}</div></div>
 <div class="card pad ng-trend"><div class="rowhead"><h2>Six-month trend</h2><span class="small">All nine functions</span></div><div class="chartbars">${months6.map(m=>{let vals=FN.map(f=>statTeam(f,m).score).filter(v=>v!==null),v=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;return `<div class="barcol"><strong>${score(v)}</strong><div class="bar" style="height:${v===null?2:Math.max(3,v*1.42)}px;background:${v===null?'#e6eaf0':'#88acf5'}"></div><span class="blabel">${new Date(m+'-01T12:00:00').toLocaleString('en-GB',{month:'short'})}</span></div>`}).join('')}</div><p class="small" style="margin-top:14px">Unreported KPIs contribute zero to monthly totals. Reporting completion is shown separately.</p></div>
 </div></section>
 </div>`;
}
const FUNCTION_OWNERS=['Emmanuella Yayra Faho','Nana Akua Bensua Ofori-Addo','Prince Abeka Adams','Maame Esi Owuo Agyemang','Victor Attopley','Lawrencia Naa Edwards','Harrison Addo','Gifty Odamea Offei','Janet Dansowah'];
function teamCard(f){let z=statTeam(f);return `<div class="card team" data-team="${esc(f)}"><div class="flex"><h3 class="grow">${esc(f)}</h3><span class="status ${teamMood(z)}">${teamStatus(z)}</span></div><div class="score">${score(z.score)}</div>${bar(z.score)}<div class="meta"><span>${z.count} of ${z.total} KPIs reported</span><span>View details ↗</span></div></div>`}function teamsPage(){return `<div class="rowhead"><h2>All nine functions</h2><span class="small">Select a function to review and update</span></div><div class="teams">${FN.map(teamCard).join('')}</div><div class="section card pad" id="details"><div class="rowhead"><h2>Function details</h2><select class="select" id="teamPicker">${FN.map(f=>`<option ${f===chosenTeam?'selected':''}>${esc(f)}</option>`).join('')}</select></div>${teamDetails()}</div>`}
function teamDetails(){let ks=activeKpis().filter(k=>k.team===chosenTeam);return `<p class="small">${esc(FUNCTION_OWNERS[FN.indexOf(chosenTeam)]||'')} · Five monthly KPIs</p>${chosenTeam===OPS_TEAM?operationsNotice():''}<div class="tablewrap"><table><thead><tr><th>Indicator</th><th>Target</th><th>Actual</th><th>Achievement</th><th>Status</th><th></th></tr></thead><tbody>${ks.map(k=>{let r=getRecord(k),v=result(k);return `<tr><td><div class="tname">${esc(k.name)}</div><div class="small">${esc(k.description)}</div></td><td>${formatVal(r.target??k.target,k.unit)}</td><td>${formatVal(r.actual,k.unit)}</td><td style="min-width:105px">${score(v)}${bar(v)}</td><td><span class="status ${mood(v)}">${kpiStatus(k)}</span></td><td>${canEditKpi(k.id)?`<button class="btn sm" data-edit="${k.id}">Update</button><button class="btn sm" type="button" data-onclick="openEvidence('${k.id}')">Evidence</button>`:'<span class="small">View only</span>'}</td></tr>${r.note?`<tr><td colspan="6" class="small"><strong>Note:</strong> ${esc(r.note)}</td></tr>`:''}`}).join('')||'<tr><td colspan="6" class="empty">No KPIs configured yet.</td></tr>'}</tbody></table></div>`}function updatesPage(){return `${chosenTeam===OPS_TEAM||chosenTeam==='ALL'?operationsNotice():''}<div class="card pad"><div class="rowhead"><h2>Monthly performance entries</h2><div class="filters"><select class="select" id="teamPicker"><option value="ALL">All functions</option>${FN.map(f=>`<option ${f===chosenTeam?'selected':''}>${esc(f)}</option>`).join('')}</select><button class="btn primary" data-onclick="openAdd()">+ Add indicator</button></div></div><div class="tablewrap"><table><thead><tr><th>Function / KPI</th><th>Target</th><th>Actual</th><th>Achievement</th><th>Updated</th><th>Action</th></tr></thead><tbody>${activeKpis().filter(k=>chosenTeam==='ALL'||k.team===chosenTeam).map(k=>{let r=getRecord(k);return `<tr><td><div class="tname">${esc(k.name)}</div><div class="small">${esc(k.team)}</div></td><td>${formatVal(r.target??k.target,k.unit)}</td><td>${formatVal(r.actual,k.unit)}</td><td><span class="status ${mood(result(k))}">${score(result(k))}</span></td><td class="small">${r.updated?new Date(r.updated).toLocaleDateString('en-GB'):'Not reported'}</td><td>${canEditKpi(k.id)?`<button class="btn sm" data-edit="${k.id}">Update</button><button class="btn sm" type="button" data-onclick="openEvidence('${k.id}')">Evidence</button>`:'<span class="small">View only</span>'}</td></tr>`}).join('')}</tbody></table></div></div>`}function reportsPage(){let s=allStat(),bad=FN.filter(f=>{let z=statTeam(f);return z.count>0&&z.score<70}),pending=FN.filter(f=>statTeam(f).count!==statTeam(f).total),notes=state.notes[month]||{};return `<div class="two"><div class="card pad reportblock"><div class="rowhead"><h2>Executive monthly brief</h2><button class="btn sm" data-onclick="window.print()">Print report</button></div><p><strong>Reporting period:</strong> ${monthName(month)}<br><strong>Cross-functional score:</strong> ${score(s.score)}<br><strong>Completed functions:</strong> ${s.submitted}/9<br><strong>KPIs with actuals:</strong> ${s.filled}/${s.total}</p>${operationsNotice()}<ol>${operationsKpis().map(k=>`<li><strong>${esc(k.name)}</strong> — ${esc(k.description)} <span>Achievement: ${score(result(k))}</span></li>`).join('')}</ol><h3>Performance exceptions</h3><p>${bad.length?bad.map(x=>esc(x)).join(', ')+' currently below 70%.':'No function with reported results is below 70%.'}</p><h3>Outstanding updates</h3><p>${pending.length?pending.map(x=>esc(x)).join(', '):'All functions have submitted all their KPIs.'}</p><h3>Summary</h3><p>${esc(notes.summary||'No management summary recorded yet.')}</p><h3>Risks and blockers</h3><p>${esc(notes.risks||'No risks recorded yet.')}</p><h3>Priorities for next month</h3><p>${esc(notes.actions||'No priorities recorded yet.')}</p><p class="note">Draft performance report generated from the available entries. Validate figures before formal submission.</p></div><div class="card pad"><h2 style="font-size:17px">Management commentary</h2><p class="small">Save your context separately for each reporting month.</p><div class="field" style="margin-top:18px"><label>Executive summary</label><textarea id="summaryNote" rows="5" placeholder="What worked well this month?">${esc(notes.summary||'')}</textarea></div><div class="field" style="margin-top:14px"><label>Key risks and blockers</label><textarea id="riskNote" rows="4" placeholder="Which issues need leadership attention?">${esc(notes.risks||'')}</textarea></div><div class="field" style="margin-top:14px"><label>Next-month actions</label><textarea id="actionNote" rows="4" placeholder="What should happen next?">${esc(notes.actions||'')}</textarea></div><button class="btn primary" style="margin-top:15px" id="saveNotes">Save monthly commentary</button></div></div><div class="section card pad"><h2 style="font-size:17px">Functional summary</h2><div class="tablewrap"><table><thead><tr><th>Function</th><th>Score</th><th>Completion</th><th>Status</th></tr></thead><tbody>${FN.map(f=>{let z=statTeam(f);return `<tr><td>${esc(f)}</td><td>${score(z.score)}</td><td>${z.count}/${z.total}</td><td><span class="status ${teamMood(z)}">${teamStatus(z)}</span></td></tr>`}).join('')}</tbody></table></div></div>`}function settingsPage(){return `<div class="two"><div class="card pad"><h2 style="font-size:17px;margin:0">KPI configuration</h2><p class="small">Five official monthly KPIs per function. Agreed milestones and prospect targets require administrator scoring setup.</p><div class="tablewrap"><table><thead><tr><th>Indicator</th><th>Owner function</th><th>Default target</th><th></th></tr></thead><tbody>${activeKpis().map(k=>`<tr><td>${esc(k.name)}</td><td>${esc(k.team)}</td><td>${formatVal(k.target,k.unit)}</td><td><button class="btn sm" data-config="${k.id}">Edit</button></td></tr>`).join('')}</tbody></table></div><button class="btn primary" style="margin-top:17px" data-onclick="openAdd()">+ Create KPI</button></div><div><div class="card pad"><h2 style="font-size:17px;margin:0">Data backup</h2><p class="small">Your records are stored locally in this web browser, not a central database.</p><button class="btn primary" id="exportBtn">↓ Export backup (JSON)</button><div style="margin-top:11px"><button class="btn" id="importBtn">↑ Import backup</button></div><p class="note">Export regularly, especially before changing browsers, devices or clearing browser data. Import replaces the dashboard's existing data.</p></div><div class="card pad" style="margin-top:17px"><h2 style="font-size:17px;margin:0">Score logic</h2><p class="small">Achievement = actual ÷ target × 100 for higher-is-better metrics; target ÷ actual × 100 for lower-is-better metrics. Scores are capped at 100%.</p><p class="small">Each of the five KPIs contributes 20% to its function score. Team performance averages all nine functions. Unreported or unconfigured KPIs contribute zero to monthly totals and remain separately labelled.</p><p class="small">Guide: 90–100% On track, 70–89% Watch, under 70% Needs attention. These rules are editable in a future version.</p><div class="help"><strong>Important:</strong> No login, shared database, or permissions are included in this offline edition. Avoid storing sensitive employee or payroll-level personal data.</div></div></div></div>`}

function lastSix(){let d=new Date(month+'-01T12:00:00'),m=[];for(let i=0;i<6;i++){m.push(d.toISOString().slice(0,7));d.setMonth(d.getMonth()-1)}return m.reverse()}
function trendsPage(){let mm=lastSix(),scores=mm.map(m=>FN.map(f=>statTeam(f,m).score));let latest=FN.map(f=>({team:f,...statTeam(f)}));return `${heroShell('PERFORMANCE ANALYTICS','See the bigger picture.','Compare all nine functions across six months. Monthly totals include unreported KPIs at zero; reporting status is shown separately.','↗ Last 6 months')}<div class="card pad"><div class="rowhead"><h2>Six-month department scorecard</h2><span class="small">Results are capped at 100%</span></div><div class="tablewrap"><table class="matrix"><thead><tr><th>Functional team</th>${mm.map(m=>`<th>${new Date(m+'-01T12:00:00').toLocaleString('en-GB',{month:'short',year:'2-digit'})}</th>`).join('')}<th>Latest</th></tr></thead><tbody>${FN.map((f,i)=>`<tr><td>${esc(f)}</td>${scores.map((col,j)=>{let n=col[i],reported=statTeam(f,mm[j]).count;return `<td class="${!reported?'nil':n>=90?'ok':n>=70?'mid':'low'}">${score(n)}${!reported?'<div class="small">Not reported</div>':''}</td>`}).join('')}<td><span class="status ${teamMood(latest[i])}">${teamStatus(latest[i])}</span></td></tr>`).join('')}</tbody></table></div><div style="margin-top:10px"><span class="legendkey"><i style="background:#c1f2dd"></i>On track (90–100)</span><span class="legendkey"><i style="background:#ffe6af"></i>Watch (70–89)</span><span class="legendkey"><i style="background:#ffccd6"></i>Attention (below 70)</span><span class="legendkey"><i style="background:#e7ebf1"></i>Not reported</span></div></div><div class="section two"><div class="card pad"><div class="rowhead"><h2>Current month — ranked view</h2><span class="small">All nine functions</span></div><div class="group-list">${latest.slice().sort((a,b)=>(b.score??-1)-(a.score??-1)).map(z=>`<div class="group-item"><div class="label">${esc(z.team)}</div>${bar(z.score)}<strong>${score(z.score)}</strong></div>`).join('')}</div></div><div class="card pad"><h2>What this means</h2><p class="small">Each KPI carries 20% of its function score. All nine functions count in the team average. A missing report contributes zero to the monthly score; it remains labelled Not reported.</p><div class="help"><strong>For leadership:</strong> investigate low scores, confirm data submission, and document actions in Monthly Report.</div><button class="btn primary" data-onclick="changeView('slides')" style="margin-top:20px">Open presentation →</button></div></div>`}
