function slidesPage(){let s=allStat(),rank=FN.map(f=>({f,...statTeam(f)})).sort((a,b)=>(b.score??-1)-(a.score??-1)),pending=rank.filter(x=>x.count<x.total),notes=state.notes[month]||{};
let slides=[
`<div class="kicker">NEXTGEN LEADERSHIP TEAM · ${monthName(month).toUpperCase()}</div><h2>Monthly Performance<br>Command Centre</h2><div class="display">${score(s.score)}</div><p>Cross-functional achievement · ${s.filled}/${s.total} KPI entries received</p>`,
`<div class="kicker">01 · AT A GLANCE</div><h2>Executive overview</h2><div class="stats" style="grid-template-columns:repeat(2,minmax(0,1fr));margin-top:25px"><div class="card stat"><div class="k">Overall achievement</div><div class="v">${score(s.score)}</div></div><div class="card stat"><div class="k">Functions complete</div><div class="v">${s.submitted}/9</div></div><div class="card stat"><div class="k">Entries recorded</div><div class="v">${s.filled}/${s.total}</div></div><div class="card stat"><div class="k">Pending teams</div><div class="v">${pending.length}</div></div></div>`,
`<div class="kicker">02 · PERFORMANCE RANKING</div><h2>How our functions performed</h2><div class="group-list" style="margin-top:20px">${rank.map(z=>`<div class="group-item"><div class="label">${esc(z.f)}</div>${bar(z.score)}<strong>${score(z.score)}</strong></div>`).join('')}</div>`,
`<div class="kicker">03 · MANAGEMENT INSIGHTS</div><h2>Highlights & priorities</h2><h3>Executive summary</h3><p>${esc(notes.summary||'No summary has been recorded for this month.')}</p><h3>Risks and blockers</h3><p>${esc(notes.risks||'No risks recorded.')}</p><h3>Next-month priorities</h3><p>${esc(notes.actions||'No next-month actions recorded.')}</p>`,
`<div class="kicker">04 · ACTION REQUIRED</div><h2>Reporting follow-up</h2><p><strong>${pending.length}</strong> functions still have incomplete reporting.</p><div class="group-list" style="margin-top:16px">${pending.map(z=>`<div class="group-item"><div class="label" style="width:auto">${esc(z.f)}</div><span class="status none">${z.count}/${z.total} recorded</span></div>`).join('')||'<p>All functions have completed reporting.</p>'}</div><div class="help">Validate all figures with function owners before formally submitting this presentation.</div>`
];slideIndex=Math.max(0,Math.min(slideIndex,slides.length-1));return `${heroShell('LEADERSHIP PRESENTATION','Present with confidence.','Five clean slides generated from the chosen reporting month. Add your commentary under Monthly Report.',monthName(month))}<div class="slidenav no-print"><span class="small">Slide ${slideIndex+1} of ${slides.length}</span><div class="actions"><button class="btn" id="prevSlide">← Previous</button><button class="btn primary" id="nextSlide">Next →</button><button class="btn" id="slidesPrint">Print / PDF</button></div></div><div class="slide">${slides[slideIndex]}<div class="slidefoot"><span>L’AINE HR · NEXTGEN LEADERSHIP</span><span>${slideIndex+1} / ${slides.length}</span></div></div><p class="small">Presentation is based on your live entries for ${monthName(month)}. Save as PDF with your browser’s Print function.</p>`}
function bindScreen(){document.querySelectorAll('[data-team]').forEach(x=>x.onclick=()=>{chosenTeam=x.dataset.team;view='functions';render()});document.querySelectorAll('[data-edit]').forEach(x=>x.onclick=()=>openUpdate(x.dataset.edit));document.querySelectorAll('[data-config]').forEach(x=>x.onclick=()=>openConfig(x.dataset.config));let p=document.getElementById('teamPicker');if(p)p.onchange=()=>{chosenTeam=p.value;render()};let sn=document.getElementById('saveNotes');if(sn)sn.onclick=()=>{if(cloudMode&&cloudRole!=='admin')return;state.notes[month]={summary:document.getElementById('summaryNote').value,risks:document.getElementById('riskNote').value,actions:document.getElementById('actionNote').value};persist();toast('Commentary saved');render()};let ex=document.getElementById('exportBtn');if(ex)ex.onclick=exportData;let im=document.getElementById('importBtn');if(im)im.onclick=()=>document.getElementById('importFile').click();let pr=document.getElementById('prevSlide');if(pr)pr.onclick=()=>{slideIndex--;render()};let nx=document.getElementById('nextSlide');if(nx)nx.onclick=()=>{slideIndex++;render()};let sp=document.getElementById('slidesPrint');if(sp)sp.onclick=()=>window.print()}
function showModal(title,body,onSave){document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML=body;document.getElementById('saveModal').onclick=onSave;document.getElementById('modalBack').classList.add('show')}function closeModal(){document.getElementById('modalBack').classList.remove('show')}function val(id){return document.getElementById(id)?.value}
function canEditKpi(id){const k=activeKpis().find(k=>k.id===id);return !!k&&(!cloudMode||cloudRole==='admin'||(cloudRole==='viewer'&&k.team===assignedFunction));}
function openUpdate(id){if(!canEditKpi(id))return toast('You can edit only your assigned function.');if(cloudMode&&cloudRole!=='admin'&&cloudRole!=='viewer')return;let k=activeKpis().find(x=>x.id===id);if(!k)return;if(k.unit==='unconfigured'||k.target==null){showModal('Manual scoring setup required',`<p><strong>${esc(k.name)}</strong> — ${esc(k.description)}</p><p>No compatible scoring definition exists. Agree the unit and target with the role owner before entering a score. Evidence may still be attached below.</p>${evidenceControls(k.id)}`,closeModal);return;}let r=getRecord(k);showModal('Update monthly KPI',`${k.officialOperations?`<p class="small">Evidence source: ${OPS_EVIDENCE}</p>`:''}<div class="help"><strong>${esc(k.team)} · ${esc(k.name)}</strong><div class="small">${esc(k.description)}</div><div class="small">Reporting period: ${monthName(month)}</div></div><div class="fields"><div class="field"><label>Monthly target</label><input id="fTarget" type="number" step="any" value="${esc(r.target??k.target)}" ${cloudMode&&cloudRole==='viewer'?'readonly':''}></div><div class="field"><label>Actual result</label><input id="fActual" type="number" step="any" placeholder="Enter result" value="${esc(r.actual??'')}"></div></div><div class="field"><label>Comment / explanation / action taken</label><textarea id="fNote" rows="4" placeholder="Reasons for variance, next steps…">${esc(r.note||'')}</textarea></div><div class="help small">Direction: <strong>${k.direction==='lower'?'Lower is better':'Higher is better'}</strong> · Unit: ${esc(k.unit)}</div>${evidenceControls(k.id)}`,async()=>{if(contributorSaving)return;let t=Number(val('fTarget')),a=val('fActual');if(val('fTarget')===''||!Number.isFinite(t)||t<0){alert('Enter a valid non-negative target.');return}if(a!==''&&(!Number.isFinite(Number(a))||Number(a)<0)){alert('Enter a valid non-negative result.');return}if(k.officialOperations&&!state.kpis.some(x=>x.id===k.id))state.kpis.push({...k});state.actuals[month] ||= {};const entry={target:t,actual:a===''?null:Number(a),note:val('fNote'),updated:new Date().toISOString()};if(cloudMode&&cloudRole==='viewer'){try{await cloudSaveContributor(id,entry);closeModal();render();toast('KPI saved securely')}catch(e){toast('KPI not saved: '+e.message)}return;}state.actuals[month][id]=entry;persist();closeModal();render();toast(cloudMode?'Saving KPI…':'KPI updated successfully')})}
function configFields(k={}){return `<div class="fields"><div class="field"><label>Function</label><select class="select" id="cTeam">${FN.map(f=>`<option ${f===k.team?'selected':''}>${esc(f)}</option>`).join('')}</select></div><div class="field"><label>Indicator name</label><input id="cName" value="${esc(k.name||'')}" placeholder="e.g., Training revenue"></div><div class="field"><label>Unit</label><select class="select" id="cUnit">${[['count','Count'],['percent','Percentage'],['ghs','Ghana cedis'],['days','Days']].map(([v,n])=>`<option value="${v}" ${v===k.unit?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Default monthly target</label><input id="cTarget" type="number" step="any" min="0" value="${esc(k.target??'')}"></div><div class="field"><label>Better performance means…</label><select class="select" id="cDirection"><option value="higher" ${k.direction!=='lower'?'selected':''}>Higher result</option><option value="lower" ${k.direction==='lower'?'selected':''}>Lower result</option></select></div><div class="field"><label>Score weight (default 1)</label><input id="cWeight" type="number" step="0.1" min="0.1" value="${esc(k.weight||1)}"></div></div><div class="field"><label>Description</label><textarea id="cDesc" rows="3" placeholder="Define exactly how this KPI is measured">${esc(k.description||'')}</textarea></div>${k.id?`<button class="btn danger sm" id="deleteKpi" style="margin-top:12px">Delete indicator</button>`:''}`}
function readConfig(k){if(k.officialKpi){const t=Number(val('cTarget'));if(val('cTarget')===''||!Number.isFinite(t)||t<=0)return alert('Enter a positive agreed target.');k.unit=val('cUnit');k.target=t;return true;}if(false){alert('Operations & Analytics Officer has exactly five official KPIs. Scoring or historical identity mapping requires manual review; this generic editor cannot change this role.');return false;}let name=val('cName').trim(),tar=Number(val('cTarget')),wei=Number(val('cWeight'));if(!name||val('cTarget')===''||!Number.isFinite(tar)||tar<0||!Number.isFinite(wei)||wei<=0){alert('Please provide an indicator name, non-negative target and positive weight.');return false}Object.assign(k,{team:val('cTeam'),name,unit:val('cUnit'),target:tar,direction:val('cDirection'),weight:wei,description:val('cDesc')});return true}function openConfig(id){if(cloudMode&&cloudRole!=='admin')return;let k=activeKpis().find(x=>x.id===id);if(!k)return;showModal('Edit indicator',configFields(k),()=>{if(!readConfig(k))return;persist();closeModal();render();toast('KPI definition saved')});if(k.officialKpi){document.getElementById('deleteKpi').style.display='none';['cTeam','cName','cDesc','cWeight','cDirection'].forEach(id=>document.getElementById(id).disabled=true);}document.getElementById('deleteKpi').onclick=()=>{if(confirm('Delete this KPI and its historical entries?')){state.kpis=state.kpis.filter(x=>x.id!==id);Object.values(state.actuals).forEach(a=>delete a[id]);persist();closeModal();render();toast('KPI deleted')}}}function openAdd(){return toast('Each function has five official KPIs. Edit scoring targets in Settings & Data.');if(cloudMode&&cloudRole!=='admin')return;showModal('Create new indicator',configFields({team:FN[0],direction:'higher',unit:'count',weight:1}),()=>{let k={id:'k'+Date.now()};if(!readConfig(k))return;state.kpis.push(k);persist();closeModal();render();toast('New indicator created')})}function exportData(){let blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='NextGen-Performance-Backup-'+month+'.json';a.click();URL.revokeObjectURL(url)}document.getElementById('importFile').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let data=JSON.parse(await f.text());if(!Array.isArray(data.kpis)||!data.actuals||!data.notes)throw Error('Invalid backup format');if(cloudMode&&cloudRole!=='admin')throw Error('Read-only users cannot import backups.');if(confirm('Replace ALL current dashboard data with this backup?')){state=data;persist();render();toast('Backup imported')}}catch(err){alert('Could not import: '+err.message)}e.target.value=''};document.querySelectorAll('.navbtn').forEach(b=>b.onclick=()=>{view=b.dataset.view;if(view==='updates')chosenTeam='ALL';render()});document.getElementById('monthSelect').onchange=e=>{month=e.target.value;render()};document.getElementById('addBtn').onclick=()=>{view='updates';chosenTeam='ALL';render();openAdd()};document.getElementById('authBtn').onclick=()=>openOnlinePanel();document.getElementById('printBtn').onclick=()=>{view='reports';render();window.print()};document.getElementById('modalBack').onclick=e=>{if(e.target.id==='modalBack')closeModal()};window.changeView=(v)=>{view=v;render()};
const CLOUD_CFG_KEY='nextgen_cloud_config_v1',CLOUD_SESSION_KEY='nextgen_cloud_session_v1';
const NEXTGEN_PROJECT={url:'https://fxzdrbxadlmguyekmseb.supabase.co',anon:'sb_publishable_MovqlibZOeHjt4hQ8ThwPg_VevgMKvI'};
let cloudConfig=NEXTGEN_PROJECT,cloudSession=null,cloudMode=false,cloudVersion=0,cloudBusy=false,cloudRole=null,cloudPending=null,cloudConflict=false;
try{cloudConfig=NEXTGEN_PROJECT;localStorage.setItem(CLOUD_CFG_KEY,JSON.stringify(cloudConfig));localStorage.removeItem(CLOUD_SESSION_KEY);cloudSession=null}catch(_){}
function onlineUrl(path){return cloudConfig.url.replace(/\/$/,'')+path}
async function cloudRequest(path,method='GET',body=null,auth=true){
 let res;
 if(path.startsWith('/auth/v1/token?grant_type=password'))res=await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'login',...body})});
 else if(path.startsWith('/auth/v1/recover'))res=await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'recover',email:body.email})});
 else res=await fetch('/api/backend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path,method,body})});
 const data=await res.json();if(!res.ok)throw Error(data?.message||data?.msg||data?.error_description||data?.error||('HTTP '+res.status));return data;
}
async function cloudRefresh(){const r=await fetch('/api/session',{cache:'no-store'});if(!r.ok)throw Error('Sign in required');cloudSession=await r.json();return true;}
async function cloudCall(path,method='GET',body=null){return cloudRequest(path,method,body);}
let assignedFunction=null,contributorSaving=false,functionReports=[],ownFunctionReport={};
async function cloudLoad(){
 if(await cloudCall('/rest/v1/rpc/nextgen_password_status','POST',{})){showPasswordSetup();return;}
 const security=await cloudCall('/rest/v1/rpc/nextgen_security_status','POST',{});if(security.mfa_required){await showMfaSetup();return;}
 if(cloudBusy||contributorSaving)throw Error('Wait for the current save to finish.');
 const scoped=await cloudCall('/rest/v1/rpc/nextgen_launch_scope','POST',{});
 if(!['admin','contributor'].includes(scoped?.role)||!Array.isArray(scoped.state?.kpis))throw Error('No assigned function access is available.');
 const nextState={kpis:scoped.state.kpis,actuals:scoped.state.actuals||{},notes:scoped.state.notes||{}};
 cloudRole=scoped.role==='contributor'?'viewer':'admin';assignedFunction=scoped.function||null;
 state=nextState;cloudVersion=scoped.version;cloudPending=null;cloudConflict=false;
 functionReports=await cloudCall('/rest/v1/nextgen_monthly_reports?reporting_month=eq.'+encodeURIComponent(month)+'&select=function_name,summary,risks,actions,status');if(cloudRole!=='admin'){if(view==='settings')view='overview';await loadFunctionReport();}
 cloudMode=true;document.body.classList.remove('auth-locked');
 document.getElementById('localBanner').textContent=cloudRole==='admin'?'Online workspace connected. Administrator access enabled.':'Assigned workspace: '+assignedFunction+'. View all team results; edit only your own function.';
 document.getElementById('authBtn').textContent=cloudRole==='admin'?'● Administrator':'● '+assignedFunction;
 render();
}
async function loadFunctionReport(){
 const rows=await cloudCall('/rest/v1/nextgen_monthly_reports?function_name=eq.'+encodeURIComponent(assignedFunction)+'&reporting_month=eq.'+encodeURIComponent(month)+'&select=summary,risks,actions,status');
 ownFunctionReport=rows?.[0]||{};
}
async function saveFunctionReport(){
 if(contributorSaving)return;
 const button=document.getElementById('saveFunctionReport');button.disabled=true;
 const report={function_name:assignedFunction,reporting_month:month,summary:val('summaryNote'),risks:val('riskNote'),actions:val('actionNote')};
 try{contributorSaving=true;
 const path='/rest/v1/nextgen_monthly_reports?function_name=eq.'+encodeURIComponent(assignedFunction)+'&reporting_month=eq.'+encodeURIComponent(month);
 const existing=await cloudCall(path+'&select=function_name');
 await cloudCall(existing?.length?path:'/rest/v1/nextgen_monthly_reports',existing?.length?'PATCH':'POST',report);
 ownFunctionReport=report;functionReports=functionReports.filter(r=>r.function_name!==assignedFunction).concat(report);toast('Monthly report saved securely');
 }catch(e){toast('Report not saved: '+e.message)}finally{contributorSaving=false;button.disabled=false;}
}
async function cloudSave(){
 if(cloudRole!=='admin')return;
 cloudPending=JSON.parse(JSON.stringify(state));
 if(cloudBusy||cloudConflict)return;
 cloudBusy=true;
 try{while(cloudPending){
  const snapshot=cloudPending;cloudPending=null;
  const rows=await cloudCall('/rest/v1/dashboard_workspaces?id=eq.1&version=eq.'+cloudVersion,'PATCH',{state:snapshot,version:cloudVersion+1});
  if(!rows?.length){cloudConflict=true;cloudPending=JSON.parse(JSON.stringify(state));throw Error('Another session changed the workspace. Export your changes, then Reload online before editing again.');}
  cloudVersion=rows[0].version;
 }toast('Changes synced securely');
 }catch(e){cloudPending=JSON.parse(JSON.stringify(state));document.getElementById('localBanner').textContent='Changes not synced: '+e.message;toast('Sync failed: '+e.message);}
 finally{cloudBusy=false;}
}
async function cloudSaveContributor(kpiId,record){
 if(cloudRole!=='viewer'||contributorSaving)throw Error('Wait for the current save to finish.');
 const actual=record.actual===null?null:Number(record.actual);
 if(actual!==null&&(!Number.isFinite(actual)||actual<0))throw Error('Enter a non-negative numeric actual.');
 contributorSaving=true;
 try{const version=await cloudCall('/rest/v1/rpc/nextgen_launch_save_actual','POST',{p_kpi:kpiId,p_month:month,p_actual:actual,p_note:String(record.note||'').slice(0,10000),p_version:cloudVersion});
 cloudVersion=version;state.actuals[month]||={};state.actuals[month][kpiId]={...record};
 }finally{contributorSaving=false;}
}
const oldPersist=persist;persist=function(){if(cloudMode){if(cloudRole!=='admin'){toast('Use the KPI Update action to save your assigned actual.');return}cloudSave();return}oldPersist()};
