const originalUpdatesPage=updatesPage,originalReportsPage=reportsPage;
updatesPage=function(){if(!cloudMode||cloudRole!=='viewer')return originalUpdatesPage();return '<div class="card pad"><h2>'+esc(assignedFunction)+' · Monthly KPI entries</h2><p class="small">Targets are set by the administrator. Update your actual results and notes, then wait for confirmation that they saved.</p>'+teamDetails()+'</div>';};
function teamReportSummary(){const n=state.notes[month]||{};return '<div class="card pad"><h2>Team monthly performance · '+monthName(month)+'</h2><p>Overall achievement: '+score(allStat().score)+'</p><div class="tablewrap"><table><thead><tr><th>Function</th><th>Achievement</th><th>KPIs reported</th></tr></thead><tbody>'+FN.map(f=>{const z=statTeam(f);return '<tr><td>'+esc(f)+'</td><td>'+score(z.score)+'</td><td>'+z.count+'/'+z.total+'</td></tr>';}).join('')+'</tbody></table></div><h3>Management summary</h3><p>'+esc(n.summary||'No summary recorded.')+'</p><p>'+esc(n.risks||'')+'</p><p>'+esc(n.actions||'')+'</p><h3>Function reports</h3>'+functionReports.map(r=>'<article><h4>'+esc(r.function_name)+'</h4><p>'+esc(r.summary)+'</p><p><strong>Risks:</strong> '+esc(r.risks)+'</p><p><strong>Next actions:</strong> '+esc(r.actions)+'</p></article>').join('')+'</div><div style="height:16px"></div>';}
reportsPage=function(){if(!cloudMode||cloudRole!=='viewer')return originalReportsPage()+'<div class="section card pad"><h2>Function monthly reports</h2>'+functionReports.map(r=>'<article><h3>'+esc(r.function_name)+'</h3><p><strong>Summary:</strong> '+esc(r.summary)+'</p><p><strong>Risks:</strong> '+esc(r.risks)+'</p><p><strong>Next actions:</strong> '+esc(r.actions)+'</p></article>').join('')+'</div>';const n=ownFunctionReport;return teamReportSummary()+'<div class="card pad"><h2>'+esc(assignedFunction)+' · Monthly report</h2><p>'+monthName(month)+'</p><div class="field"><label for="summaryNote">Monthly summary</label><textarea id="summaryNote" rows="5">'+esc(n.summary||'')+'</textarea></div><div class="field"><label for="riskNote">Risks and blockers</label><textarea id="riskNote" rows="4">'+esc(n.risks||'')+'</textarea></div><div class="field"><label for="actionNote">Next-month actions</label><textarea id="actionNote" rows="4">'+esc(n.actions||'')+'</textarea></div><button class="btn primary" id="saveFunctionReport">Save monthly report</button></div>';};
document.getElementById('monthSelect').onchange=async e=>{if(contributorSaving||cloudBusy||cloudPending){e.target.value=month;return toast('Wait for the current save to finish.');}month=e.target.value;if(cloudMode){try{await cloudLoad()}catch(error){toast('Could not load month: '+error.message);}}else render();};
function evidenceControls(id){return `<div class="evidence-box"><strong>Supporting evidence</strong><p class="small">PNG, PDF, DOC, DOCX or XLSX · maximum 1 MB (1,000,000 bytes) per file. Evidence is visible to your function and the administrator. Files remain quarantined until a malware scan clears them. Evidence achievement is unverified.</p><div class="actions"><button class="btn sm" type="button" data-onclick="submitEvidenceLink('${id}')">Add document link</button><label class="btn sm">Import evidence<input type="file" accept=".png,.pdf,.doc,.docx,.xlsx" hidden data-onchange="uploadEvidenceFile('${id}',this.files[0]);this.value='' "></label><button class="btn sm" type="button" data-onclick="loadEvidence('${id}')">Refresh attachments</button></div><div id="evidenceList-${id}" class="small">Choose Refresh attachments to view saved evidence.</div></div>`;}
function openEvidence(id){if(!canEditKpi(id))return toast('Evidence is private to the assigned function and administrator.');showModal('KPI evidence · '+monthName(month),evidenceControls(id),closeModal);loadEvidence(id);}
async function loadEvidence(id){try{const rows=await cloudCall('/rest/v1/nextgen_kpi_evidence?kpi_id=eq.'+encodeURIComponent(id)+'&reporting_month=eq.'+month+'&select=id,label,kind,url,size_bytes,created_at,scan_status&order=created_at.desc');const el=document.getElementById('evidenceList-'+id);if(el)el.innerHTML=rows.length?rows.map(r=>`<p>${r.kind==='link'?`<a target="_blank" rel="noopener noreferrer" href="${esc(r.url)}">${esc(r.label)}</a>`:(r.scan_status==='clean'?`<button class="btn sm" type="button" data-onclick="downloadEvidence('${r.id}')">Download ${esc(r.label)}</button>`:`${esc(r.label)} · ${r.scan_status==='rejected'?'Blocked by security scan':'Quarantined: awaiting malware scan'}`)+` (${r.size_bytes.toLocaleString()} bytes)`} · Unverified</p>`).join(''):'No evidence attached for this month.';}catch(e){toast('Could not load evidence: '+e.message);}}
async function submitEvidenceLink(kpiId){if(!cloudMode||!canEditKpi(kpiId))return;const value=prompt('Paste the document link (HTTP or HTTPS):');if(!value)return;try{const u=new URL(value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||value.length>2048||/[\u0000-\u0020]/.test(value))throw Error('Use a valid HTTP or HTTPS document link without credentials.');await cloudCall('/rest/v1/nextgen_kpi_evidence','POST',{kpi_id:kpiId,reporting_month:month,kind:'link',label:'Document link',url:u.href});toast('Document link saved');await loadEvidence(kpiId);}catch(e){toast('Link not saved: '+e.message);}}
async function uploadEvidenceFile(kpiId,file){if(!file||!cloudMode||!canEditKpi(kpiId))return;if(file.size>1000000||!file.size)return toast('Choose a non-empty file no larger than 1 MB.');try{toast('Uploading evidence…');const res=await fetch('/api/evidence',{method:'POST',headers:{'x-kpi-id':kpiId,'x-reporting-month':month,'x-file-name':encodeURIComponent(file.name),'content-type':file.type||'application/octet-stream'},body:file});const data=await res.json();if(!res.ok)throw Error(data.error||'Upload denied');toast(data.scan_status==='clean'?'Evidence saved securely':'Evidence uploaded and quarantined pending malware scan');await loadEvidence(kpiId);}catch(e){toast('Evidence not saved: '+e.message);}}
async function downloadEvidence(id){try{const r=await fetch('/api/evidence/'+id,{cache:'no-store'});if(!r.ok)throw Error('Download denied');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=decodeURIComponent(r.headers.get('x-file-name')||'evidence');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast(e.message);}}

function lockLogin(message=''){
 document.body.classList.add('auth-locked');cloudMode=false;cloudRole=null;
 cloudSession=null;localStorage.removeItem(CLOUD_SESSION_KEY);assignedFunction=null;functionReports=[];ownFunctionReport={};state={kpis:[],actuals:{},notes:{}};document.getElementById('screen').replaceChildren();
 document.getElementById('loginMessage').textContent=message;
}
function signInMessage(e){
 if(/invalid login credentials/i.test(e.message))return 'Your email or password is incorrect. Please try again.';
 if(/email not confirmed/i.test(e.message))return 'Please confirm your email using the link in your inbox before signing in.';
 if(/not yet been granted|membership|workspace not available/i.test(e.message))return 'Your account does not have NextGen access yet. Please contact the dashboard administrator.';
 if(/fetch|network/i.test(e.message))return 'Unable to connect. Check your internet connection and try again.';
 return e.message||'Unable to sign in. Please try again.';
}
document.getElementById('loginForm').onsubmit=async e=>{
 e.preventDefault();const button=document.getElementById('loginSubmit');button.disabled=true;button.textContent='Signing in…';
 document.getElementById('loginMessage').textContent='';
 try{
  cloudConfig=NEXTGEN_PROJECT;
  const data=await cloudRequest('/auth/v1/token?grant_type=password','POST',{email:document.getElementById('loginEmail').value.trim(),password:document.getElementById('loginPassword').value},false);
  cloudSession=data;
  await cloudLoad();if(document.getElementById('loginPassword'))document.getElementById('loginPassword').value='';
 }catch(error){lockLogin(signInMessage(error));}
 finally{button.disabled=false;button.textContent='Sign in';}
};
function openOnlinePanel(){
 showModal('Your account',`<p>You are signed in as <strong>${esc(cloudSession?.user?.email||'')}</strong>.</p><p class="small">${cloudRole==='admin'?'Administrator · Edit KPI results and reports.':'Assigned contributor · Update your function’s KPI results and monthly report.'}</p><div class="actions"><button class="btn" id="refreshWorkspace">Refresh dashboard</button><button class="btn danger" id="signOutAccount">Sign out</button></div><p id="accountMessage" class="small" role="status"></p>`,closeModal);
 document.getElementById('refreshWorkspace').onclick=async()=>{try{await cloudLoad();closeModal();toast('Dashboard refreshed');}catch(e){document.getElementById('accountMessage').textContent=signInMessage(e);}};
 document.getElementById('signOutAccount').onclick=async()=>{
  if(cloudBusy||cloudPending||contributorSaving){document.getElementById('accountMessage').textContent='Some changes have not synced. Refresh or export a backup before signing out.';return;}
  try{await cloudCall('/auth/v1/logout','POST');}catch(e){document.getElementById('accountMessage').textContent='Could not sign out. Check your connection and try again.';return;}
  closeModal();document.getElementById('loginPassword').value='';lockLogin();
 };
};
const NG_HELP_TOPICS=[['start','Getting started'],['score','KPI scores'],['update','Update figures'],['report','Monthly reports'],['compare','Comparisons'],['status','Reporting status'],['access','My access'],['sync','Saving & sync']];
const helpPanel=document.getElementById('ngHelpPanel'),helpLaunch=document.getElementById('ngHelpLaunch'),helpLog=document.getElementById('ngHelpLog');
function helpMessage(text,user=false,action=null){
 const box=document.createElement('div');box.className='ng-help-message'+(user?' user':'');box.textContent=text;
 if(action){const button=document.createElement('button');button.type='button';button.className='ng-help-action';button.textContent=action.label;button.onclick=()=>{if(!cloudMode)return;if(action.view==='settings'&&cloudRole!=='admin'){helpAnswer('access');return;}changeView(action.view);if(action.view==='updates'){chosenTeam='ALL';render();}helpToggle(false);};box.appendChild(button);}
 helpLog.appendChild(box);helpLog.scrollTop=helpLog.scrollHeight;
}
function helpToggle(open){if(open&&!cloudMode)return;helpPanel.hidden=!open;helpLaunch.setAttribute('aria-expanded',String(open));if(open){if(!helpLog.children.length)helpMessage('Hello! I can guide you around NextGen, explain KPI scores and show reporting progress. Choose a topic below, or type a short question.');document.getElementById('ngHelpInput').focus();}else helpLaunch.focus();}
function helpAnswer(topic){
 const admin=cloudRole==='admin';let text='',action=null;
 switch(topic){
 case 'start':text='Choose your reporting month at the top of the dashboard. Overview gives you a summary across all nine functions. Select Functional Teams to see each function’s KPIs. Monthly Report and Presentation use the month you have selected.';action={label:'Open overview',view:'overview'};break;
 case 'score':text='For higher-is-better KPIs: actual ÷ target × 100. For lower-is-better KPIs: target ÷ actual × 100. Scores are capped at 100%. A zero actual on a lower-is-better metric scores 100%; a zero target on a higher-is-better metric also scores 100%.\n\nEach of the five KPIs contributes 20% to a function’s score. One KPI achieved at 100% therefore contributes 20 percentage points. Overall performance averages all nine functions. Unreported and unconfigured KPIs contribute zero to monthly totals. Reporting completion is shown separately; missing results remain labelled Not reported.\n\n90–100%: On track. 70–89%: Watch. Below 70%: Needs attention. Review configured targets with function leads before reporting.';break;
 case 'update':text=admin?'Select the reporting month, open KPI Updates, find the indicator and choose Update. Enter its target, actual result and a comment, then save. Wait for “Changes synced securely” before closing the dashboard. You can add or edit KPI definitions under Settings & Data.':'Open KPI Updates to enter your own function’s results and notes. Other functions are view only. Evidence remains private to your function and the administrator.';action={label:admin?'Open KPI Updates':'View functional teams',view:admin?'updates':'functions'};break;
 case 'report':text='Choose the month first, then open Monthly Report to view the executive brief, exceptions and outstanding updates.'+(admin?' Add the summary, risks and next-month actions under Management commentary, then save.':' Management commentary is maintained by the administrator.')+' Use Print / PDF to save a report through your browser. Presentation offers five slides based on the selected month. Validate figures before formal submission.';action={label:'Open monthly report',view:'reports'};break;
 case 'compare':text='Comparisons shows a six-month department scorecard ending in the selected reporting month, plus the current ranking. Unreported results contribute zero to monthly scores and are labelled separately. A score compares achievement against configured targets; it does not compare raw output volume between functions.';action={label:'Open comparisons',view:'trends'};break;
 case 'status':{const s=allStat(),pending=FN.map(f=>({name:f,...statTeam(f)})).filter(f=>f.count<f.total);text=monthName(month)+': '+s.filled+' of '+s.total+' KPI results recorded; '+s.submitted+' of 9 functions complete.\n\n'+(pending.length?'Outstanding updates:\n'+pending.map(f=>f.name+': '+f.count+'/'+f.total+' recorded').join('\n'):'All configured KPI results have been recorded.')+'\n\nThis reflects the data currently loaded. Refresh your account’s dashboard to fetch the latest shared results.';action={label:'View functional teams',view:'functions'};break;}
 case 'access':text=admin?'You are signed in as Administrator. You can update figures, KPI definitions and management commentary. Leadership viewers can read results and reports. Account access is managed separately; this help chat cannot grant permissions.':'You can view all team performance tabs and reports. You can edit only your assigned function’s results and monthly report, and upload its evidence. Settings and KPI target definitions are administrator-only.';break;
 case 'sync':text='The signed-in dashboard loads shared results from your NextGen workspace. Administrator changes sync after saving. A “Changes synced securely” message confirms completion.\n\nIf a save fails, keep this page open, check your connection and export a backup from Settings & Data if you are the administrator. If another session changed the workspace, export your changes before refreshing. Click your account button at the top for Refresh dashboard or Sign out. Never enter employee-level personal or payroll data.';break;
 default:text='I can help with dashboard navigation, KPI scores, updates, monthly reports, comparisons, reporting status, access and syncing. Choose one of the topics below. For an issue outside these topics, contact the dashboard administrator.';
 }
 helpMessage(text,false,action);
}
function helpTopicFor(question){const q=question.toLowerCase();if(/pending|outstanding|complete|completion|submitted|reporting status|how many|missing/.test(q))return 'status';if(/score|scor|achievement|calculate|calculation|percent|weight|target|threshold/.test(q))return 'score';if(/compar|trend|rank|six.month/.test(q))return 'compare';if(/report|print|pdf|presentation|slide|commentary/.test(q))return 'report';if(/save|sync|offline|network|connection|refresh|conflict|backup|export/.test(q))return 'sync';if(/access|permission|role|viewer|sign.out|logout|login|sign.in|password/.test(q))return 'access';if(/update|edit|enter|figure|add|actual|kpi/.test(q))return 'update';if(/start|navigate|navigation|help|hello|^hi$|overview|use/.test(q))return 'start';return 'unknown';}
for(const [key,label] of NG_HELP_TOPICS){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=()=>{helpMessage(label,true);helpAnswer(key);};document.getElementById('ngHelpTopics').appendChild(b);}
