 const form=document.getElementById('loginForm');form.innerHTML='<h2>Set up your NextGen password</h2><p>This private link is for one team member and can be used once. Continue only if the administrator sent this link to you.</p><button class="btn primary" id="recoveryContinue">Continue to choose my password</button><p id="loginMessage" role="status"></p>';
 form.onsubmit=async e=>{e.preventDefault();const button=document.getElementById('recoveryContinue');button.disabled=true;try{const response=await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'verify-recovery',token_hash:token})});const data=await response.json();if(!response.ok)throw Error(data.error);cloudSession=data;token='';showPasswordSetup();}catch(error){document.getElementById('loginMessage').textContent=signInMessage(error);button.disabled=false;}};
