async function showMfaSetup(){
 cloudMode=false;cloudRole=null;state={kpis:[],actuals:{},notes:{}};document.getElementById('screen').replaceChildren();document.body.classList.add('auth-locked');
 const form=document.getElementById('loginForm');form.innerHTML='<h2>Protect your administrator account</h2><p id="mfaIntro">Use Microsoft Authenticator, Google Authenticator or another authenticator app.</p><div id="mfaQr"></div><p id="mfaSecret" class="small"></p><div class="login-field"><label for="mfaCode">Six-digit code</label><input id="mfaCode" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" required></div><button class="btn primary" id="mfaSubmit">Verify and open dashboard</button><p id="mfaMessage" role="status"></p><button class="btn" type="button" id="mfaLogout">Sign out</button>';
 document.getElementById('mfaLogout').onclick=async()=>{await cloudCall('/auth/v1/logout','POST');location.reload();};
 let factor;try{const user=await cloudCall('/auth/v1/user');factor=user.factors?.find(f=>f.factor_type==='totp'&&f.status==='verified');if(!factor){for(const old of user.factors||[]){if(old.factor_type==='totp'&&old.status!=='verified')await cloudCall('/auth/v1/factors/'+old.id,'DELETE');}factor=await cloudCall('/auth/v1/factors','POST',{factor_type:'totp',friendly_name:'NextGen administrator'});const img=document.createElement('img');img.alt='Scan this private QR code in your authenticator app';img.width=200;img.height=200;img.src=factor.totp.qr_code.startsWith('data:image/svg+xml')?factor.totp.qr_code:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(factor.totp.qr_code);document.getElementById('mfaQr').append(img);document.getElementById('mfaSecret').textContent='Manual setup key: '+factor.totp.secret;document.getElementById('mfaIntro').textContent='Scan this QR code in your authenticator app, then enter its six-digit code. Keep access to your authenticator.';}}catch(e){document.getElementById('mfaMessage').textContent=signInMessage(e);}
 form.onsubmit=async e=>{e.preventDefault();const button=document.getElementById('mfaSubmit');button.disabled=true;try{if(!factor?.id)throw Error('Reload and sign in to retry authenticator setup.');const c=await cloudCall('/auth/v1/factors/'+factor.id+'/challenge','POST',{});const result=await cloudCall('/auth/v1/factors/'+factor.id+'/verify','POST',{challenge_id:c.id,code:document.getElementById('mfaCode').value.trim()});cloudSession=result;location.reload();}catch(e){document.getElementById('mfaMessage').textContent=signInMessage(e);}finally{button.disabled=false;}};
}
render();
const authFragment=new URLSearchParams(location.hash.slice(1));
if(authFragment.has('token_hash')){const token=authFragment.get('token_hash');history.replaceState(null,'',location.pathname+location.search);showRecoveryConfirmation(token);}
else if(authFragment.has('access_token')&&authFragment.has('refresh_token')){
 const recovery={action:'recovery',access_token:authFragment.get('access_token'),refresh_token:authFragment.get('refresh_token')};history.replaceState(null,'',location.pathname+location.search);
 fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(recovery)}).then(async r=>{const data=await r.json();if(!r.ok)throw Error(data.error);cloudSession=data;showPasswordSetup();}).catch(e=>lockLogin(signInMessage(e)));
}else if(authFragment.has('error_description')){const message=authFragment.get('error_description');history.replaceState(null,'',location.pathname+location.search);lockLogin(message);}
else{const btn=document.getElementById('loginSubmit');btn.disabled=true;btn.textContent='Restoring session…';cloudRefresh().then(()=>cloudLoad()).catch(()=>{}).finally(()=>{btn.disabled=false;btn.textContent='Sign in';});}

// Fixed action dispatcher: no eval or inline executable attributes.
document.addEventListener('click',event=>{const el=event.target.closest?.('[data-onclick]');if(!el)return;const action=el.dataset.onclick;const simple={'closeModal()':closeModal,'openAdd()':openAdd,'window.print()':()=>window.print()};if(simple[action])return simple[action]();const match=/^(changeView|openEvidence|loadEvidence|submitEvidenceLink|downloadEvidence)\('([\w-]+)'\)$/.exec(action||'');if(!match)return;({changeView,openEvidence,loadEvidence,submitEvidenceLink,downloadEvidence})[match[1]](match[2]);});
document.addEventListener('change',event=>{const el=event.target;if(!el.dataset?.onchange)return;const match=/^uploadEvidenceFile\('([\w-]+)',this.files\[0\]\);this.value=''\s*$/.exec(el.dataset.onchange);if(match){uploadEvidenceFile(match[1],el.files[0]);el.value='';}});
